const rows = $input.all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]).filter(r => r && r.id);
if (!rows.length) {
  return [{ json: { has_asset: false, action: 'skip', message: 'No pending package assets for WF04.5.' } }];
}
const asset = rows[0];
return [{ json: { has_asset: true, asset } }];

const picked = $('Code: pick pending asset').first().json;
const asset = picked.asset;
const packageRows = $('Supabase: read package').all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]).filter(r => r && r.id);
const queueRows = $input.all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]).filter(r => r && r.id);
const pkg = packageRows[0] || {};
const queue = queueRows[0] || {};
const variant = queue.content_variants || {};
const safeText = v => {
  if (!v) return '';
  if (typeof v === 'string') return v;
  try { return JSON.stringify(v); } catch (e) { return String(v); }
};
const arr = v => Array.isArray(v) ? v : [];
const parseJson = v => typeof v === 'string' ? (() => { try { return JSON.parse(v); } catch(e) { return []; } })() : v;
const screen = parseJson(variant.screen_text_json);
const scenes = parseJson(variant.scene_plan_json);
const fallbackHook = 'Смотри, как меняется пространство';
const fallbackCta = 'Напиши в директ, чтобы обсудить свой стол';
const hook = variant.first_frame || variant.hook_text || asset.caption || fallbackHook;
const cta = asset.cta || variant.cta || pkg.cta || fallbackCta;
const textLines = [];
for (const x of arr(screen)) textLines.push(safeText(x.text || x.screen_text || x.title || x));
for (const x of arr(scenes)) textLines.push(safeText(x.text || x.action || x.visual || x));
if (!textLines.length && asset.caption) textLines.push(asset.caption);
const base = {
  asset_id: asset.id,
  daily_package_id: asset.daily_package_id,
  asset_type: asset.asset_type,
  content_queue_id: asset.content_queue_id,
  package_date: pkg.package_date,
  caption: asset.caption || variant.caption || '',
  cta,
};
const oldAiId = String(asset.qc_notes || '').match(/polza_media_id=([A-Za-z0-9_\-]+)/)?.[1] || null;
let http_method = 'POST';
let render_url = 'http://85.239.59.252:8003/render';
let render_tool = 'ffmpeg_typewriter';
let render_body;
if (oldAiId && asset.qc_status === 'processing') {
  http_method = 'GET';
  render_url = 'https://polza.ai/api/v1/media/' + oldAiId;
  render_tool = 'polza_ai_video_status';
  render_body = {};
} else if (queue.production_mode === 'ai_video' || asset.render_tool === 'polza_sora_2') {
  render_url = 'https://polza.ai/api/v1/media';
  render_tool = 'polza_ai_video';
  const prompt = [
    variant.ai_video_prompt || '',
    'Vertical 9:16 premium custom table reel, realistic, high retention first seconds.',
    'Hook: ' + hook,
    'Scene plan: ' + textLines.slice(0, 6).join(' | '),
    'CTA mood: ' + cta,
    'Avoid third-party logos, recognizable faces, copied competitor branding, unreadable text.'
  ].filter(Boolean).join('\n');
  render_body = {
    model: 'openai/sora-2',
    input: {
      prompt,
      aspect_ratio: '9:16',
      duration: 12,
      quality: 'standard',
      watermark: false
    },
    provider: {
      allow_fallbacks: true,
      only: ['OpenAI', 'Google'],
      order: ['OpenAI', 'Google'],
      sort: 'quality'
    },
    async: true,
    user: 'content-factory'
  };
} else if (asset.asset_type === 'story' || asset.render_tool === 'playwright' || queue.production_mode === 'story_template') {
  render_url = 'http://85.239.59.252:8004/render_chat';
  render_tool = 'playwright_chat';
  const messages = textLines.slice(0, 6).map((text, i) => ({ from: i % 2 === 0 ? 'client' : 'me', text }));
  if (!messages.length) messages.push({ from: 'client', text: hook }, { from: 'me', text: cta });
  render_body = { messages, theme: 'dark_premium', duration: 12 };
} else if (asset.asset_type === 'reel_premium' || queue.queue_group === 'premium') {
  render_tool = 'ffmpeg_result_card';
  render_body = {
    type: 'result_card',
    business_name: 'Стол на заказ',
    metrics: textLines.slice(0, 4),
    tagline: hook,
    cta,
    bg_color: '#0d0d0d',
    duration: 12,
    resolution: '1080x1920'
  };
} else {
  render_tool = 'ffmpeg_typewriter';
  render_body = {
    type: 'typewriter',
    hook,
    texts: textLines.slice(0, 6),
    solution: cta,
    bg_color: asset.asset_type === 'reel_viral' ? '#111111' : '#0d0d0d',
    duration: 12,
    resolution: '1080x1920'
  };
}
return [{ json: { ...base, http_method, render_url, render_tool, render_body } }];

const req = $('Code: build render request').first().json;
const response = $input.first()?.json || {};
const now = new Date().toISOString();
function firstUrl(data) {
  if (!data) return null;
  if (typeof data === 'string' && /^https?:\/\//.test(data)) return data;
  if (Array.isArray(data)) return firstUrl(data[0]);
  if (typeof data === 'object') return data.url || data.file_url || data.video_url || data.download_url || data.output_url || data.data?.url || null;
  return null;
}
let ok = false;
let body;
if (req.render_tool.startsWith('polza_ai_video')) {
  const mediaId = response.id || response.generation_id || response.task_id || null;
  const status = String(response.status || '').toLowerCase();
  const url = firstUrl(response.data) || firstUrl(response.output) || firstUrl(response.result) || firstUrl(response.content);
  if ((status === 'completed' || status === 'succeeded' || status === 'success') && url) {
    ok = true;
    body = {
      file_path: url,
      storage_url: url,
      qc_status: 'passed',
      qc_notes: 'AI video rendered by Polza via ' + (response.model || 'openai/sora-2'),
      duration_seconds: req.render_body?.input?.duration || 12,
      resolution: '1080x1920',
      updated_at: now
    };
  } else if (mediaId || status === 'pending' || status === 'processing') {
    body = {
      qc_status: 'processing',
      qc_notes: 'Polza AI video is processing; polza_media_id=' + (mediaId || 'unknown') + '; status=' + (status || 'pending'),
      updated_at: now
    };
  } else {
    body = {
      qc_status: 'failed',
      qc_notes: 'Polza AI video failed: ' + (response.error?.message || response.message || JSON.stringify(response).slice(0, 500)),
      updated_at: now
    };
  }
} else {
  ok = response.success === true && !!response.file_path;
  body = ok ? {
    file_path: response.file_path,
    storage_url: response.file_url || null,
    qc_status: 'passed',
    qc_notes: 'Rendered by WF04.5 via ' + req.render_tool,
    duration_seconds: req.render_body?.duration || 12,
    resolution: '1080x1920',
    updated_at: now
  } : {
    qc_status: 'failed',
    qc_notes: 'Render failed in WF04.5: ' + (response.message || response.error || JSON.stringify(response).slice(0, 500)),
    updated_at: now
  };
}
return [{ json: { asset_id: req.asset_id, daily_package_id: req.daily_package_id, ok, update_body: body, render_response: response } }];

const rows = $input.all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]).filter(r => r && r.id);
const render = $('Code: build asset update').first().json;
const package_ready = rows.length === 0;
return [{ json: { package_ready, daily_package_id: render.daily_package_id, rendered_asset_id: render.asset_id, blocking_assets: rows.map(r => ({ id: r.id, asset_type: r.asset_type, qc_status: r.qc_status })) } }];
